function registerValidateYaml(server, env, partnerToken) {
  server.tool(
    toolName("validate_yaml"),
    "Dry-run YAML \u6821\u9A57\u3002\u4E0D\u90E8\u7F72\u3001\u7121 side effect\u3002\u56DE {valid, errors?, nodeCount, edgeCount}\u3002**\u6C38\u9060\u5148 call \u6B64 tool \u518D push_workflow**\uFF0C\u907F\u514D\u53CD\u8986 deploy \u5931\u6557\u3002",
    {
      graph: external_exports.object({
        nodes: external_exports.array(external_exports.unknown()).describe("workflow \u7BC0\u9EDE\u9663\u5217"),
        edges: external_exports.array(external_exports.unknown()).describe("workflow \u908A\u9663\u5217 (cypher binding \u4E09\u5143\u7D44)")
      }).passthrough().describe("workflow graph object\uFF08\u5DF2 parse \u904E YAML \u7684\u7D50\u69CB\uFF0C\u975E raw YAML string\uFF09")
    },
    async ({ graph }) => {
      try {
        const res = await cypherFetch(env, "/validate", {
          apiKey: partnerToken,
          method: "POST",
          body: graph
        });
        const body = await res.json().catch(() => null);
        if (!res.ok || !body?.valid) {
          return errorResponse(
            "validation_failed",
            body?.errors ? `\u6821\u9A57\u5931\u6557\uFF0C${body.errors.length} \u500B\u932F\u8AA4` : `\u6821\u9A57\u5931\u6557 HTTP ${res.status}`,
            [
              "\u4F9D errors \u9663\u5217\u9010\u9805\u4FEE\u6539 YAML",
              "\u82E5 errors \u63D0\u5230 '\u672A\u77E5\u95DC\u4FC2\u8A5E'\uFF0C\u770B design.md \xA73 \u5217\u51FA\u7684\u5408\u6CD5\u95DC\u4FC2\u8A5E",
              "\u82E5 errors \u63D0\u5230 'node \u4E0D\u5B58\u5728'\uFF0C\u6AA2\u67E5 edges \u7684 from/to \u662F\u5426\u62FC\u932F"
            ],
            JSON.stringify(body?.errors ?? body)
          );
        }
        return successResponse(body, [
          `\u6821\u9A57\u901A\u904E\uFF1A${body.nodeCount} \u500B\u7BC0\u9EDE / ${body.edgeCount} \u689D\u908A`,
          "\u53EF\u4EE5 call arcrun_push_workflow \u90E8\u7F72\u4E86"
        ]);
      } catch (e) {
        return errorResponse(
          "internal_error",
          `validate \u5167\u90E8\u932F\uFF1A${e instanceof Error ? e.message : String(e)}`,
          ["\u91CD\u8A66\u4E00\u6B21", "\u82E5\u6301\u7E8C\u5931\u6557\uFF0C\u544A\u8A34 leo \u4E26\u8CBC\u932F\u8AA4\u8A0A\u606F"]
        );
      }
    }
  );
}
