 // \u7F72\u540D\u9023\u7D50\uFF1A\u6C99\u7BB1\u88E1\u76F4\u63A5\u9EDE\u4E0D\u958B\uFF0C\u4EA4\u7D66\u5BBF\u4E3B\u958B\uFF08ui/open-link\uFF09\u3002\n    var link = mountEl.querySelector(\'.arcrun-a2ui-credit a\');\n    if (link) link.addEventListener(\'click\', function (e) { e.preventDefault(); request(\'ui/open-link\', { url: link.href }).catch(function () {}); });\n    if (st.kind === \'app\' && st.live) {\n      st.busy = true; push(merge({ status: \'\u8B80\u53D6\u4E2D\u2026\' }));\n      callApp(surf.load, {}).then(function (r) {\n        st.busy = false;\n        var sd = surfaceOf(r);\n        push(sd ? Object.assign({}, st.init, sd, { status: \'\' }) : merge({ status: \'\u2717 \u8B80\u4E0D\u5230\uFF1A\u52D5\u4F5C\u6C92\u6709\u56DE\u756B\u9762\u8CC7\u6599\' }));\n      }).catch(function (e) { st.busy = false; push(merge({ status: \'\u2717 \u8B80\u4E0D\u5230\uFF1A\' + errText(e) })); });\n    }\n    document.documentElement.setAttribute(\'data-rendered\', st.kind);\n  }\n\n  function onToolResult(p) {\n    var sc = p && p.structuredContent;\n    if (!sc || !sc.surface || !Array.isArray(sc.surface.components)) {\n      showHint(humanError(textOf(p)) || \'\u9019\u6B21\u5DE5\u5177\u6C92\u6709\u56DE\u756B\u9762\u3002\', true);\n      return;\n    }\n    render(sc);\n  }\n\n  window.addEventListener(\'message\', function (ev) {\n    if (ev.source !== window.parent) return;\n    var d = ev.data;\n    if (!d || d.jsonrpc !== \'2.0\') return;\n    if (d.method === undefined && d.id !== undefined) {\n      var p = pending[d.id]; if (!p) return;\n      delete pending[d.id];\n      if (d.error) p.reject(new Error(d.error.message || \'error\')); else p.resolve(d.result);\n      return;\n    }\n    switch (d.method) {\n      case \'ui/notifications/tool-result\': onToolResult(d.params); break;\n      case \'ui/notifications/tool-cancelled\': showHint(\'\u9019\u6B21\u5DE5\u5177\u88AB\u53D6\u6D88\u4E86\u3002\', true); break;\n      case \'ui/notifications/host-context-changed\': applyContext(d.params); break;\n      case \'ui/resource-teardown\': if (d.id !== undefined) respond(d.id, {}); break;\n      case \'ping\': if (d.id !== undefined) respond(d.id, {}); break;\n      default: break;\n    }\n  });\n\n  if (window.ResizeObserver) {\n    var lastH = 0;\n    new ResizeObserver(function () {\n      var h = Math.ceil(document.documentElement.getBoundingClientRect().height);\n      if (h !== lastH) { lastH = h; notify(\'ui/notifications/size-changed\', { width: Math.ceil(window.innerWidth), height: h }); }\n    }).observe(document.documentElement);\n  }\n\n  request(\'ui/initialize\', { appInfo: { name: \'arcrun-surface\', version: \'1.0.0\' }, appCapabilities: {}, protocolVersion: PROTOCOL })\n    .then(function (r) { applyContext(r && r.hostContext); notify(\'ui/notifications/initialized\', {}); })\n    .catch(function (e) { showHint(\'\u8DDF\u5BBF\u4E3B\u63E1\u624B\u5931\u6557\uFF1A\' + errText(e), true); });\n})();\n<\/script>\n</body>\n</html>\n';

// mcp/src/tools/arcrun_mcp_apps.ts
var SURFACE_VIEW_URI = "ui://arcrun/surface";
var MCP_APP_MIME = "text/html;profile=mcp-app";
var ID_RE = /^[A-Za-z0-9_.-]{1,64}$/;
function structured(text, sc) {
  return { content: [{ type: "text", text }], structuredContent: sc };
}
function needPortal(identity) {
  if (identity.kind === "stale") return staleIdentityError();
  if (identity.kind !== "portal") {
    return errorResponse("login_required", "\u5C0D\u8A71\u5167\u756B\u9762\u9700\u8981\u4EE5 Portal \u5E33\u865F\u767B\u5165\u7684 MCP \u9023\u7DDA\uFF08\u756B\u9762\u4E0A\u7684\u6309\u9215\u8981\u7528\u767B\u5165\u8005\u7684\u8EAB\u5206\u57F7\u884C\uFF09", [
      "\u7528 Portal \u5E33\u5BC6\u91CD\u65B0\u9023\u7DDA MCP \u5F8C\u518D\u8A66"
    ]);
  }
  return null;
}
function registerAllMcpAppTools(server, env, partnerToken, identity) {
  registerSurfaceResource(server);
  registerOpenApp(server, env, identity);
  registerShowSurface(server, env, partnerToken);
  registerSurfaceAction(server, env, identity);
}
function registerSurfaceResource(server) {
  server.registerResource(
    "arcrun_surface_view",
    SURFACE_VIEW_URI,
    {
      title: "Arcrun \u5C0D\u8A71\u5167\u756B\u9762",
      description: "\u628A Arcrun \u7684 A2UI \u5BA3\u544A\u5F0F\u756B\u9762\uFF08App \u7684 ui.surface\uFF0C\u6216 AI \u7576\u5834\u7D44\u7684\u756B\u9762\uFF09\u756B\u5728\u5C0D\u8A71\u88E1\u3002",
      mimeType: MCP_APP_MIME
    },
    async (uri) => ({
      contents: [
        {
          uri: uri.href,
          mimeType: MCP_APP_MIME,
          text: SURFACE_VIEW_HTML,
          // 不需要任何外部來源（渲染器已內嵌）：CSP 全空＝最嚴的預設。
          _meta: { ui: { prefersBorder: true, csp: {} } }
        }
      ]
    })
  );
}
function registerOpenApp(server, env, identity) {
  server.registerTool(
    toolName("open_app"),
    {
      title: "\u5728\u5C0D\u8A71\u88E1\u6253\u958B App \u7684\u756B\u9762",
      description: "\u628A\u9019\u500B\u79DF\u6236\u88DD\u7684 App \u7684\u756B\u9762\u76F4\u63A5\u986F\u793A\u5728\u5C0D\u8A71\u88E1\uFF08\u4E0D\u5FC5\u8B93\u4F7F\u7528\u8005\u53BB Portal \u958B\uFF09\uFF1A\u4EFB\u4F55\u5E36\u5BA3\u544A\u5F0F\u756B\u9762\uFF08ui.surface\uFF09\u7684 App \u90FD\u884C\u2014\u2014arcrun_create_form \u505A\u7684\u8868\u55AE\u3001\u6216\u4F60\u7528 cypher \u610F\u5716\u5DE5\u4F5C\u6D41\uFF0B\u756B\u9762\u5BA3\u544A\u63A8\u4E0A\u53BB\u7684 App\u3002\u4F7F\u7528\u8005\u5728\u756B\u9762\u4E0A\u586B\u5BEB\u3001\u6309\u6309\u9215\uFF0C\u8D70\u7684\u662F\u8DDF Portal \u540C\u4E00\u689D App \u52D5\u4F5C\uFF08\u53EA\u80FD\u89F8\u767C App \u5BA3\u544A\u904E\u7684\u52D5\u4F5C\uFF09\uFF0C\u8868\u55AE\u9001\u51FA\u5F8C\u5BEB\u9032\u5B83\u7684\u8CC7\u6599\u8868\uFF1B\u4E4B\u5F8C\u7528 kbdb_query\uFF0Fkbdb_get_record \u8B80\u56DE\u4F86\u6838\u5C0D\u3002App \u4EE3\u865F\uFF08app\uFF09\uFF1D App \u7684 id\uFF08\u8868\u55AE\uFF1D\u5EFA\u7ACB\u6642\u7684 name\uFF09\u3002\u53EA\u6709\u5BA3\u544A\u5F0F\u756B\u9762\u80FD\u5728\u5C0D\u8A71\u88E1\u986F\u793A\uFF1B\u7528\u81EA\u5E36 HTML \u7684 App \u8ACB\u4F7F\u7528\u8005\u5230 Portal \u958B\u3002",
      inputSchema: { app: external_exports.string().min(1).describe("App \u4EE3\u865F\uFF0C\u4F8B\uFF1Aleave_request") },
      annotations: { readOnlyHint: true },
      _meta: { ui: { resourceUri: SURFACE_VIEW_URI } }
    },
    async ({ app: app2 }) => {
      const gate = needPortal(identity);
      if (gate) return gate;
      if (!ID_RE.test(app2)) return errorResponse("bad_app_id", `App \u4EE3\u865F\u300C${app2}\u300D\u683C\u5F0F\u4E0D\u5C0D`, ["\u7528 App \u7684 id\uFF08\u5C0F\u5BEB\u82F1\u6578\u5E95\u7DDA\uFF09\uFF0C\u4F8B\uFF1Aleave_request"]);
      try {
        const res = await portalFetch(env, identity.portal.session, `/portal/data/apps/${encodeURIComponent(app2)}`);
        if (res.status === 404) {
          return errorResponse("app_not_found", `\u9019\u500B\u79DF\u6236\u6C92\u6709\u88DD\u540D\u70BA\u300C${app2}\u300D\u7684 App`, [
            "\u8981\u65B0\u505A\u4E00\u5F35\u8868\u55AE \u2192 arcrun_create_form",
            "\u770B\u6709\u54EA\u4E9B App \u2192 arcrun_app_tools"
          ]);
        }
        if (!res.ok) return portalError(res, `\u6253\u958B App\u300C${app2}\u300D`);
        const d = await res.json();
        if (!d.ui_surface || !Array.isArray(d.ui_surface.components)) {
          return errorResponse(
            "app_has_no_surface",
            `App\u300C${app2}\u300D\u6C92\u6709\u5BA3\u544A\u5F0F\u756B\u9762\uFF08${d.has_ui ? "\u5B83\u7528\u7684\u662F\u81EA\u5E36 HTML \u756B\u9762" : "\u5B83\u6C92\u6709\u756B\u9762"}\uFF09\uFF0C\u4E0D\u80FD\u986F\u793A\u5728\u5C0D\u8A71\u88E1\u3002`,
            ["\u8ACB\u4F7F\u7528\u8005\u5230 Portal \u7684 App \u555F\u52D5\u5668\u958B\u5B83", "\u8981\u4E00\u5F35\u80FD\u5728\u5C0D\u8A71\u88E1\u586B\u7684\u8868\u55AE \u2192 arcrun_create_form\uFF1B\u8981\u7576\u5834\u51FA\u4E00\u9801 \u2192 arcrun_show_surface"]
          );
        }
        const name = d.name || app2;
        return structured(
          `\u5DF2\u5728\u5C0D\u8A71\u88E1\u986F\u793A\u300C${name}\u300D\u7684\u756B\u9762\u3002\u4F7F\u7528\u8005\u5728\u756B\u9762\u4E0A\u64CD\u4F5C\uFF08\u586B\u5BEB\u3001\u6309\u6309\u9215\uFF09\uFF1B\u9001\u51FA\u5F8C\u8CC7\u6599\u5BEB\u9032 App \u7684\u8CC7\u6599\u8868\uFF0C\u53EF\u7528 kbdb_query \u8B80\u56DE\u6838\u5C0D\u3002`,
          {
            kind: "app",
            app: { id: d.id || app2, name, icon: d.icon || "", version: d.version || "" },
            surface: { components: d.ui_surface.components, data: d.ui_surface.data ?? {}, ...d.ui_surface.load ? { load: d.ui_surface.load } : {} }
          }
        );
      } catch (e) {
        return errorResponse("internal_error", e instanceof Error ? e.message : String(e), ["\u7A0D\u5F8C\u91CD\u8A66"]);
      }
    }
  );
}
function registerShowSurface(server, env, partnerToken) {
  server.registerTool(
    toolName("show_surface"),
    {
      title: "\u7576\u5834\u51FA\u4E00\u9801\u7D66\u4F7F\u7528\u8005\u9EDE\uFF0F\u586B",
      description: `\u8A71\u8AAA\u4E0D\u6E05\u695A\u6642\uFF0C\u76F4\u63A5\u5728\u5C0D\u8A71\u88E1\u51FA\u4E00\u500B\u756B\u9762\u8B93\u4F7F\u7528\u8005\u9EDE\u9078\u6216\u586B\u5BEB\uFF08\u91D0\u6E05\u9700\u6C42\u3001\u9078\u65B9\u6848\u3001\u6536\u5E7E\u500B\u6B04\u4F4D\uFF09\uFF0C\u7B54\u6848\u6703\u56DE\u5230\u5C0D\u8A71\u7D66\u4F60\u3002\u4F60\u7D44\u4E00\u4EFD A2UI v0.9 \u756B\u9762\uFF1Acomponents \u662F\u6241\u5E73\u6E05\u55AE\uFF0C\u6BCF\u500B\u6709\u552F\u4E00 id\uFF0C\u4E00\u5B9A\u8981\u6709 id \u70BA root \u7684\u5143\u4EF6\uFF1B\u5143\u4EF6\u53EA\u80FD\u53D6\u81EA\u756B\u9762\u5143\u4EF6\u76EE\u9304\uFF08arcrun_list_ui_components \u67E5\uFF0CText\uFF0FCard\uFF0FColumn\uFF0FRow\uFF0FList\uFF0FButton\uFF0FTextField\uFF0FChoicePicker\uFF0FDateTimeInput\uFF0FCheckBox\u2026\uFF09\u3002\u8F38\u5165\u5143\u4EF6\u7684\u503C\u7528 {"path":"/form/\u6B04\u4F4D"} \u7D81\u5728 data \u4E0A\uFF0Cdata \u7D66\u521D\u503C\uFF0C\u4F8B\uFF1Adata:{"form":{"plan":[],"note":""}}\u3002\u56DE\u8986\u6309\u9215\uFF1AButton \u7684 action \u662F {"event":{"name":"reply","context":{"plan":{"path":"/form/plan"},"note":{"path":"/form/note"}}}}\uFF0C\u4E8B\u4EF6\u540D\u53EA\u80FD\u662F reply\uFF1B\u4F7F\u7528\u8005\u6309\u4E0B\u5F8C\uFF0Ccontext \u7684\u503C\u6703\u4EE5\u8A0A\u606F\u56DE\u5230\u5C0D\u8A71\uFF08\u4F60\u4E0B\u4E00\u8F2A\u5C31\u8B80\u5F97\u5230\uFF09\u3002\u4E0D\u6536\u51FD\u5F0F\u3001\u7DB2\u5740\u3001\u8173\u672C\u3001\u4EFB\u610F HTML\uFF08\u9A57\u8B49\u4E0D\u904E\u6703\u56DE\u932F\u8AA4\u6E05\u55AE\uFF0C\u7167\u6539\u518D\u9001\uFF09\u3002\u6700\u5C0F\u7BC4\u4F8B\uFF1Acomponents:[{id:'root',component:'Card',child:'col'},{id:'col',component:'Column',children:['q','pick','btn']},{id:'q',component:'Text',text:'\u4F60\u8981\u54EA\u7A2E\uFF1F',variant:'h2'},{id:'pick',component:'ChoicePicker',label:'\u65B9\u6848',value:{path:'/form/plan'},variant:'mutuallyExclusive',options:[{label:'A',value:'a'},{label:'B',value:'b'}]},{id:'bl',component:'Text',text:'\u9001\u51FA'},{id:'btn',component:'Button',child:'bl',variant:'primary',action:{event:{name:'reply',context:{plan:{path:'/form/plan'}}}}}], data:{form:{plan:[]}}\u3002\u9019\u652F\u53EA\u51FA\u756B\u9762\u3001\u4E0D\u5BEB\u4EFB\u4F55\u8CC7\u6599\u8868\uFF1B\u8981\u6536\u8CC7\u6599\u9032\u8CC7\u6599\u8868\u8ACB\u7528 arcrun_create_form \uFF0B arcrun_open_app\u3002`,
      inputSchema: {
        title: external_exports.string().max(80).optional().describe("\u756B\u9762\u6A19\u984C\uFF08\u56DE\u8986\u6642\u6703\u5E36\u5728\u8A0A\u606F\u88E1\uFF0C\u9078\u586B\uFF09"),
        components: external_exports.array(external_exports.record(external_exports.unknown())).min(1).describe("A2UI v0.9 \u5143\u4EF6\u6E05\u55AE\uFF08\u6241\u5E73\uFF0Cid \u5F15\u7528\uFF0C\u9700\u6709 root\uFF09"),
        data: external_exports.record(external_exports.unknown()).optional().describe("\u756B\u9762\u7684\u8CC7\u6599\u6A21\u578B\uFF08\u8F38\u5165\u5143\u4EF6\u7684\u521D\u503C\uFF09\uFF0C\u9078\u586B")
      },
      annotations: { readOnlyHint: true },
      _meta: { ui: { resourceUri: SURFACE_VIEW_URI } }
    },
    async ({ title, components, data }) => {
      const surface = { components, ...data ? { data } : {} };
      try {
        const res = await cypherFetch(env, "/ui/surface/validate", { method: "POST", apiKey: partnerToken, body: { surface, actions: ["reply"] } });
        const out = await res.json().catch(() => null);
        if (!res.ok || !out?.ok) {
          const errs = out?.errors?.length ? out.errors : [`\u9A57\u8B49\u670D\u52D9\u56DE HTTP ${res.status}`];
          return errorResponse("surface_invalid", `\u756B\u9762\u5B9A\u7FA9\u4E0D\u5408\u898F\uFF1A${errs.join("\uFF1B")}`, [
            "\u7167\u932F\u8AA4\u8A0A\u606F\u4FEE\u6539\u5F8C\u518D\u547C\u53EB\u4E00\u6B21 arcrun_show_surface",
            "\u5143\u4EF6\u76EE\u9304\u8207\u5404\u5143\u4EF6\u7684\u5C6C\u6027 \u2192 arcrun_list_ui_components\uFF0Farcrun_get_ui_component"
          ]);
        }
        return structured(
          `\u5DF2\u5728\u5C0D\u8A71\u88E1\u986F\u793A\u756B\u9762${title ? `\u300C${title}\u300D` : ""}\u3002\u7B49\u4F7F\u7528\u8005\u64CD\u4F5C\uFF1A\u4ED6\u6309\u4E0B\u56DE\u8986\u6309\u9215\u5F8C\uFF0C\u7B54\u6848\u6703\u4EE5\u4E00\u5247\u300C\u3010\u756B\u9762\u56DE\u8986\u3011\u2026\u300D\u8A0A\u606F\u56DE\u5230\u5C0D\u8A71\uFF0C\u4F60\u518D\u63A5\u8457\u8655\u7406\u3002`,
          { kind: "adhoc", title: title ?? "", surface }
        );
      } catch (e) {
        return errorResponse("internal_error", e instanceof Error ? e.message : String(e), ["\u7A0D\u5F8C\u91CD\u8A66"]);
      }
    }
  );
}
function registerSurfaceAction(server, env, identity) {
  server.registerTool(
    toolName("surface_action"),
    {
      title: "\u756B\u9762\u6309\u9215\u89F8\u767C App \u52D5\u4F5C\uFF08\u53EA\u7D66\u756B\u9762\u547C\u53EB\uFF09",
      description: "\u5C0D\u8A71\u5167\u756B\u9762\u7684\u6309\u9215\u547C\u53EB\u9019\u652F\uFF1A\u4EE3\u6253 App \u5BA3\u544A\u904E\u7684\u52D5\u4F5C\uFF08\u8DDF Portal \u540C\u4E00\u689D\u3001\u540C\u4E00\u4EFD\u767D\u540D\u55AE\uFF09\u3002AI \u4E0D\u7528\u547C\u53EB\u5B83\u3002",
      inputSchema: {
        app: external_exports.string().min(1),
        action: external_exports.string().min(1),
        payload: external_exports.record(external_exports.unknown()).optional()
      },
      // 只給畫面（iframe）呼叫；宿主不會把它放進 AI 的工具清單（MCP Apps 規格 Visibility）。
      _meta: { ui: { visibility: ["app"] } }
    },
    async ({ app: app2, action, payload }) => {
      const gate = needPortal(identity);
      if (gate) return gate;
      if (!ID_RE.test(app2)) return errorResponse("bad_app_id", `App \u4EE3\u865F\u300C${app2}\u300D\u683C\u5F0F\u4E0D\u5C0D`, []);
      try {
        const res = await portalFetch(env, identity.portal.session, `/portal/data/apps/${encodeURIComponent(app2)}/action`, {
          method: "POST",
          body: { action, payload: payload ?? {} }
        });
        if (!res.ok) {
          const detail = await res.text().catch(() => "");
          let msg = detail;
          try {
            msg = JSON.parse(detail).error ?? detail;
          } catch {
          }
          if (res.status === 400 || res.status === 403 || res.status === 404) return errorResponse(`action_${res.status}`, msg || `\u52D5\u4F5C\u88AB\u62D2\u7D55\uFF08HTTP ${res.status}\uFF09`, []);
          return portalError(res, `\u57F7\u884C\u52D5\u4F5C\u300C${action}\u300D`);
        }
        const body = await res.json();
        return structured("\u52D5\u4F5C\u5DF2\u57F7\u884C\u3002", { ok: true, result: body.result ?? null });
      } catch (e) {
        return errorResponse("internal_error", e instanceof Error ? e.message : String(e), ["\u7A0D\u5F8C\u91CD\u8A66"]);
      }
    }
  );
}

// mcp/src/tools/arcrun_app_crud.ts
async function callPortal(env, identity, what, path, opts, hints) {
  if (identity.kind === "stale") return staleIdentityError();
  if (identity.kind !== "portal") {
    return errorResponse("login_required", `${what}\u9700\u8981\u4EE5 Portal \u5E33\u865F\u767B\u5165\u7684 MCP \u9023\u7DDA`, [
      "\u7528 Portal \u5E33\u5BC6\u91CD\u65B0\u9023\u7DDA MCP \u5F8C\u518D\u8A66"
    ]);
  }
  try {
    let res = await portalFetch(env, identity.portal.session, path, opts);
    let rounds = 1;
    let json2;
    while (res.ok && opts.next) {
      json2 = await res.json();
      const q = opts.next(json2);
      if (!q || rounds >= (opts.maxRounds ?? 1)) break;
      rounds++;
      res = await portalFetch(env, identity.portal.session, path, { ...opts, query: q });
    }
    if (!res.ok) {
      if (res.status === 400 || res.status === 404 || res.status === 409) {
        const detail = await res.text().catch(() => "");
        let msg = detail;
        try {
          const j = JSON.parse(detail);
          msg = [j.error, j.hint].filter(Boolean).join("\uFF1B") || detail;
        } catch {
        }
        return errorResponse(`portal_${res.status}`, `${what}\u5931\u6557\uFF1A${msg}`, ["\u78BA\u8A8D\u540D\u7A31\u6216 id \u5F8C\u518D\u8A66"], detail);
      }
      return portalError(res, what);
    }
    return successResponse(opts.next ? json2 ?? await res.json() : await res.json(), hints);
  } catch (e) {
    return errorResponse("internal_error", e instanceof Error ? e.message : String(e), ["\u7A0D\u5F8C\u91CD\u8A66"]);
  }
}
