  card_name: "\u9019\u4E9B\u5361\u662F\u7167\u5361\u540D\uFF08\u76EE\u9304\u4E0A\u7684\u540D\u7A31\uFF09\u5C0D\u5230\u7684\uFF1B\u9019\u500B\u5EAB\u9084\u6C92\u6709\u76EE\u9304\u5361\uFF0C\u6216\u76EE\u9304\u6C92\u9EDE\u5230\u3002",
  keyword_fallback: "\u26A0\uFE0F \u76EE\u9304\u8207\u5361\u540D\u90FD\u6C92\u5C0D\u5230\uFF0C\u9019\u4E9B\u5361\u662F**\u9000\u56DE\u95DC\u9375\u5B57\u6BD4\u5C0D**\u627E\u5230\u7684\uFF0C\u53EF\u80FD\u7B54\u975E\u6240\u554F\u2014\u2014\u56DE\u7B54\u6642\u8981\u7167\u5BE6\u8AAA\u9019\u662F\u9000\u56DE\u7684\u7D50\u679C\uFF0C\u5148\u78BA\u8A8D\u5361\u7684\u5167\u5BB9\u771F\u7684\u56DE\u7B54\u4E86\u554F\u984C\u3002"
